// Ported from libcdr (https://git.libreoffice.org/libcdr): the tables of src/lib/CDRColorPalettes.h
// and the lookup of CDRParser::_resolveColorPalette. libcdr's note on the tables: they were made by
// clean-room reverse engineering (a CorelDRAW user dumped the CMYK, RGB or L*a*b* decomposition of
// the *.cpl palettes into a spreadsheet), keep only what converting an indexed colour needs, and
// hold no colour names, so they cannot serve as colour bridges. The palette names are kept in
// comments only, to make mis-conversions easier to trace.
//
// This file alone is under the MPL 2.0 (see LICENSE-MPL-2.0 beside this crate's Cargo.toml); the
// rest of the crate is MIT OR Apache-2.0.

//! CorelDRAW's built-in palettes, for palette colours (model `0x19`) and spot colours (model
//! `0x0e`), which a file stores as a palette id, an index and a tint rather than as components.

/// What a palette entry resolves to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Resolved {
    /// CMYK in percent (CorelDRAW's model `0x02`), the tint applied.
    Cmyk([u8; 4]),
    /// RGB, the tint applied over white.
    Rgb([u8; 3]),
    /// L*a*b* in CorelDRAW's model `0x12` encoding (L 0..255, a and b offset by 128).
    Lab([u8; 3]),
}

/// The colour of entry `value` (index in the low 16 bits, tint in percent in the high 16 bits) of
/// palette `palette` under colour model `model`, or `None` for an unknown palette or index.
pub fn resolve(model: u16, palette: u16, value: u32) -> Option<Resolved> {
    let ix = (value & 0xffff) as usize;
    let tint = (value >> 16) & 0xffff;
    // Most palettes count from 1; four of the CMYK ones from 0.
    let one = |t: &[u8]| ix.checked_sub(1).and_then(|i| t.get(i).copied());
    let zero = |t: &[u8]| t.get(ix).copied();
    let cmyk = |at: &dyn Fn(&[u8]) -> Option<u8>, [c, m, y, k]: [&[u8]; 4]| {
        let scale = |v: u8| u8::try_from(tint * u32::from(v) / 100).unwrap_or(u8::MAX);
        Some(Resolved::Cmyk([scale(at(c)?), scale(at(m)?), scale(at(y)?), scale(at(k)?)]))
    };
    let rgb = |[r, g, b]: [&[u8]; 3]| {
        let mix = |v: u8| u8::try_from((tint * u32::from(v) + 255 * 100u32.saturating_sub(tint)) / 100).unwrap_or(u8::MAX);
        Some(Resolved::Rgb([mix(one(r)?), mix(one(g)?), mix(one(b)?)]))
    };
    let lab = |[l, a, b]: [&[u8]; 3]| Some(Resolved::Lab([one(l)?, one(a)?, one(b)?]));
    match (model, palette) {
        (0x19, 0x03) => cmyk(&one, [P_19_03_C, P_19_03_M, P_19_03_Y, P_19_03_K]),
        (0x19, 0x08) => cmyk(&one, [P_19_08_C, P_19_08_M, P_19_08_Y, P_19_08_K]),
        (0x19, 0x09) => lab([P_19_09_L, P_19_09_A, P_19_09_B]),
        (0x19, 0x0a) => cmyk(&one, [P_19_0A_C, P_19_0A_M, P_19_0A_Y, P_19_0A_K]),
        (0x19, 0x0b) => cmyk(&one, [P_19_0B_C, P_19_0B_M, P_19_0B_Y, P_19_0B_K]),
        (0x19, 0x11) => cmyk(&one, [P_19_11_C, P_19_11_M, P_19_11_Y, P_19_11_K]),
        (0x19, 0x12) => cmyk(&one, [P_19_12_C, P_19_12_M, P_19_12_Y, P_19_12_K]),
        (0x19, 0x14) => cmyk(&one, [P_19_14_C, P_19_14_M, P_19_14_Y, P_19_14_K]),
        (0x19, 0x15) => cmyk(&one, [P_19_15_C, P_19_15_M, P_19_15_Y, P_19_15_K]),
        (0x19, 0x16) => cmyk(&one, [P_19_16_C, P_19_16_M, P_19_16_Y, P_19_16_K]),
        (0x19, 0x17) => cmyk(&one, [P_19_17_C, P_19_17_M, P_19_17_Y, P_19_17_K]),
        (0x19, 0x1a) => cmyk(&zero, [P_19_1A_C, P_19_1A_M, P_19_1A_Y, P_19_1A_K]),
        (0x19, 0x1b) => cmyk(&zero, [P_19_1B_C, P_19_1B_M, P_19_1B_Y, P_19_1B_K]),
        (0x19, 0x1c) => cmyk(&zero, [P_19_1C_C, P_19_1C_M, P_19_1C_Y, P_19_1C_K]),
        (0x19, 0x1d) => cmyk(&zero, [P_19_1D_C, P_19_1D_M, P_19_1D_Y, P_19_1D_K]),
        (0x19, 0x1e) => rgb([P_19_1E_R, P_19_1E_G, P_19_1E_B]),
        (0x19, 0x1f) => rgb([P_19_1F_R, P_19_1F_G, P_19_1F_B]),
        (0x19, 0x20) => rgb([P_19_20_R, P_19_20_G, P_19_20_B]),
        (0x19, 0x23) => cmyk(&one, [P_19_23_C, P_19_23_M, P_19_23_Y, P_19_23_K]),
        (0x19, 0x24) => cmyk(&one, [P_19_24_C, P_19_24_M, P_19_24_Y, P_19_24_K]),
        (0x19, 0x25) => cmyk(&one, [P_19_25_C, P_19_25_M, P_19_25_Y, P_19_25_K]),
        (0x0e, 0x0c) => lab([P_0E_0C_L, P_0E_0C_A, P_0E_0C_B]),
        (0x0e, 0x18) => lab([P_0E_18_L, P_0E_18_A, P_0E_18_B]),
        (0x0e, 0x21) => lab([P_0E_21_L, P_0E_21_A, P_0E_21_B]),
        (0x0e, 0x22) => lab([P_0E_22_L, P_0E_22_A, P_0E_22_B]),
        _ => None,
    }
}

