#[cfg(test)]
mod tests {
    use super::*;

    const FULL: u32 = 100 << 16;

    #[test]
    fn cmyk_palettes_scale_by_tint() {
        // Palette 0x1a counts from 0; its second entry is C 5, M 0, Y 100, K 0.
        assert_eq!(resolve(0x19, 0x1a, FULL | 1), Some(Resolved::Cmyk([5, 0, 100, 0])));
        assert_eq!(resolve(0x19, 0x1a, 50 << 16 | 1), Some(Resolved::Cmyk([2, 0, 50, 0])));
        assert_eq!(resolve(0x19, 0x03, FULL | 3), Some(Resolved::Cmyk([0, 0, 100, 0])));
    }

    #[test]
    fn rgb_palettes_tint_over_white_and_lab_ignores_tint() {
        assert_eq!(resolve(0x19, 0x1e, FULL | 1), Some(Resolved::Rgb([132, 118, 77])));
        assert_eq!(resolve(0x19, 0x1e, 1), Some(Resolved::Rgb([255, 255, 255])));
        assert_eq!(resolve(0x0e, 0x0c, 1), Some(Resolved::Lab([231, 127, 227])));
    }

    #[test]
    fn unknown_palettes_and_entries_resolve_to_nothing() {
        assert_eq!(resolve(0x19, 0x03, FULL), None, "entry 0 of a palette counting from 1");
        assert_eq!(resolve(0x19, 0x03, FULL | 3007), None);
        assert_eq!(resolve(0x19, 0x1a, FULL | 86), None);
        assert_eq!(resolve(0x19, 0x02, FULL | 1), None);
        assert_eq!(resolve(0x05, 0x03, FULL | 1), None);
        // A tint above 100 % saturates instead of wrapping.
        assert_eq!(resolve(0x19, 0x1a, 0xffff_0001), Some(Resolved::Cmyk([255, 0, 255, 0])));
    }
}
